//refAssemblies: System.Net.Sockets.dll, System.Net.Primitives.dll, System.Text.Json.dll, System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading.Tasks;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// Graceful stop: saves the game and shuts the server down through its console port (DSSaveGame, then
// DSServerShutdown), then waits for the server process of THIS service to exit. When the console does not answer
// the panel stops the server the usual way.
const string binary = "AstroServer-Win64-Shipping";
const int maxWaitSeconds = 90;

var rootPath = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\');
var root = rootPath + Path.DirectorySeparatorChar;
var rootSlash = rootPath.Replace('\\', '/') + "/";

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(binary))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    // Wine shows the executable as Z:\<root>\...\AstroServer-Win64-Shipping.exe in the command line.
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var args = File.ReadAllText(Path.Combine(dir, "cmdline")).Replace('\0', ' ').Replace('\\', '/');
            if (args.Contains(binary + ".exe", StringComparison.OrdinalIgnoreCase) && args.Contains(rootSlash, StringComparison.Ordinal))
                pids.Add(pid);
        }
        catch { } // gone meanwhile
    }
    return pids;
}

var targets = ServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}

var port = ThisService.RconPort;
var password = ThisService.Variables.ContainsKey("RconPassword") ? Convert.ToString(ThisService.Variables["RconPassword"]) : "";
try
{
    using (var console = await AstroConsole.OpenAsync(port, password, 4000))
    {
        var stats = await console.CommandAsync("DSServerStatistics", 1500, 5000);
        if (!AstroConsole.IsCompleteJson(stats))
        {
            ScriptConsole.WriteLine((object)"The server console does not answer yet (the server is still starting); the panel stops the server without saving.");
            return;
        }
        await console.CommandAsync("DSSaveGame", 3000, 15000);
        ScriptConsole.WriteLine((object)"Saved the game.");
        await console.CommandAsync("DSServerShutdown", 1000, 3000);
    }
}
catch (Exception ex)
{
    ScriptConsole.WriteLine((object)("The server console is not reachable (" + ex.Message + "); the panel stops the server without saving."));
    return;
}

ScriptConsole.WriteLine((object)"Asked the server to shut down.");
for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!ServerPids().Any(targets.Contains))
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));

// ---- ASTRONEER server console (shared by the RCON, query and stop scripts) ----
// The server's console port (ConsolePort in AstroServerSettings.ini = the service's RCON port) takes plain text lines
// over TCP: the console password first, then one command per line (DSServerStatistics, DSListPlayers, DSSaveGame,
// DSServerShutdown, ...). Commands that report something answer with one JSON object; the others answer nothing.
// This runs on the monitor of the server that hosts the service, so it connects to loopback.
sealed class AstroConsole : IDisposable
{
    readonly System.Net.Sockets.TcpClient _client = new System.Net.Sockets.TcpClient();
    System.Net.Sockets.NetworkStream _stream;

    public static async Task<AstroConsole> OpenAsync(int port, string password, int timeoutMs)
    {
        var console = new AstroConsole();
        try
        {
            var connect = console._client.ConnectAsync(System.Net.IPAddress.Loopback, port);
            if (await Task.WhenAny(connect, Task.Delay(timeoutMs)) != connect)
                throw new TimeoutException("the console port " + port + " is not answering");
            await connect;
            console._stream = console._client.GetStream();
            await console.WriteAsync(password ?? "");
            return console;
        }
        catch
        {
            console.Dispose();
            throw;
        }
    }

    public async Task WriteAsync(string line)
    {
        var bytes = System.Text.Encoding.UTF8.GetBytes(line + "\n");
        await _stream.WriteAsync(bytes, 0, bytes.Length);
        await _stream.FlushAsync();
    }

    // Reads until the reply is one complete JSON value, the server has been quiet for quietMs, or maxMs passed.
    public async Task<string> ReadReplyAsync(int quietMs, int maxMs)
    {
        var buffer = new byte[16384];
        var output = new System.IO.MemoryStream();
        var end = DateTime.UtcNow.AddMilliseconds(maxMs);
        var lastData = DateTime.UtcNow;
        while (DateTime.UtcNow < end && (DateTime.UtcNow - lastData).TotalMilliseconds < quietMs)
        {
            if (_stream.DataAvailable)
            {
                var n = await _stream.ReadAsync(buffer, 0, buffer.Length);
                if (n <= 0) break;
                output.Write(buffer, 0, n);
                lastData = DateTime.UtcNow;
                if (IsCompleteJson(System.Text.Encoding.UTF8.GetString(output.ToArray()))) break;
            }
            else
            {
                if (_client.Client.Poll(0, System.Net.Sockets.SelectMode.SelectRead) && _client.Client.Available == 0) break; // closed
                await Task.Delay(50);
            }
        }
        return System.Text.Encoding.UTF8.GetString(output.ToArray()).Trim();
    }

    public async Task<string> CommandAsync(string command, int quietMs = 1500, int maxMs = 8000)
    {
        await WriteAsync(command);
        return await ReadReplyAsync(quietMs, maxMs);
    }

    public static bool IsCompleteJson(string text)
    {
        text = (text ?? "").Trim();
        if (text.Length == 0 || (text[0] != '{' && text[0] != '[')) return false;
        try { using (System.Text.Json.JsonDocument.Parse(text)) return true; }
        catch { return false; }
    }

    public void Dispose()
    {
        try { _stream?.Dispose(); } catch { }
        try { _client.Dispose(); } catch { }
    }
}

