// (JSON, indented for reading). "help" lists the commands the server knows.
const string Help = @"ASTRONEER server console commands:
  DSServerStatistics                      server name, version, players, save, FPS
  DSListPlayers                           every known player with id, category and in-game state
  DSSaveGame [name]                       save the running game (optionally under a new name)
  DSListGames                             saved games and the active one
  DSLoadGame <name>                       load a saved game
  DSNewGame                               start a new game (save first)
  DSKickPlayerGuid <player id>            kick a player (ids from DSListPlayers)
  DSSetPlayerCategoryForPlayerName ""<name>"" <Unlisted|Blacklisted|Whitelisted|Admin|Pending|Owner>
  DSSetDenyUnlisted <true|false>          whitelist mode: only listed players may join
  DSServerShutdown                        shut the server down (the panel's Stop saves first)";

var port = Globals.Variables.Parse<int>("Port");
var password = Globals.Variables.Parse<string>("Password") ?? "";
var command = (Globals.Variables.Parse<string>("Command") ?? "").Trim();

if (command.Length == 0 || command.Equals("help", StringComparison.OrdinalIgnoreCase) || command == "?")
{
    Globals.ReturnValue = Help;
    return;
}

string reply;
try
{
    using (var console = await AstroConsole.OpenAsync(port, password, 4000))
        reply = await console.CommandAsync(command, 1500, 10000);
}
catch (Exception ex)
{
    throw new Exception("ASTRONEER console (port " + port + "): " + ex.Message);
}

if (reply.Length == 0)
{
    Globals.ReturnValue = "Sent " + command.Split(' ')[0] + " (the server does not answer this command).";
    return;
}
if (AstroConsole.IsCompleteJson(reply))
{
    using (var doc = System.Text.Json.JsonDocument.Parse(reply))
        reply = System.Text.Json.JsonSerializer.Serialize(doc.RootElement, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
}
Globals.ReturnValue = reply;

