using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using TCAdmin.SDK.Hubs.Models.GameQuery;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// ASTRONEER servers answer no server-browser query (they register with the game's own matchmaking service), so the
// server is queried over its console port: DSServerStatistics gives name, version and player counts, DSListPlayers
// the names of the players in game. The console port not answering is the normal offline reading.
string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
int port = ThisService.RconPort;
string password = ThisService.Variables.ContainsKey("RconPassword") ? Convert.ToString(ThisService.Variables["RconPassword"]) : "";

string stats, list;
try
{
    using (var console = await AstroConsole.OpenAsync(port, password, 3000))
    {
        stats = await console.CommandAsync("DSServerStatistics", 1500, 5000);
        list = AstroConsole.IsCompleteJson(stats) ? await console.CommandAsync("DSListPlayers", 1500, 5000) : "";
    }
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
    return;
}

if (!AstroConsole.IsCompleteJson(stats))
{
    // Connected, but no statistics yet: the server is still loading (or the console password is wrong).
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script",
        stats.Length == 0 ? "the server console did not answer (still starting, or wrong console password)" : "unexpected console reply: " + stats);
    return;
}

using (var s = System.Text.Json.JsonDocument.Parse(stats))
{
    var root = s.RootElement;
    string Str(string name) => root.TryGetProperty(name, out var v) ? (v.ValueKind == System.Text.Json.JsonValueKind.String ? v.GetString() : v.ToString()) : "";
    int Int(string name) => root.TryGetProperty(name, out var v) && v.ValueKind == System.Text.Json.JsonValueKind.Number ? (int)v.GetDouble() : 0;

    // Until the save is loaded the statistics carry no save name and uninitialised counters: not joinable yet.
    if (Str("saveGameName").Length == 0)
    {
        Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", "the server is still loading the save");
        return;
    }

    var players = new List<GameQueryPlayer>();
    if (AstroConsole.IsCompleteJson(list))
    {
        using (var l = System.Text.Json.JsonDocument.Parse(list))
        {
            if (l.RootElement.TryGetProperty("playerInfo", out var info) && info.ValueKind == System.Text.Json.JsonValueKind.Array)
                foreach (var p in info.EnumerateArray())
                    if (p.TryGetProperty("inGame", out var inGame) && inGame.ValueKind == System.Text.Json.JsonValueKind.True)
                        players.Add(new GameQueryPlayer { Name = p.TryGetProperty("playerName", out var n) ? n.GetString() : "" });
        }
    }

    // DSServerStatistics reports the advertised id the server generates (ServerAdvertisedName); the name players see
    // is ServerName in AstroServerSettings.ini.
    var name = "";
    try
    {
        var ini = System.IO.Path.Combine((string)ThisService.RootDirectory, "Astro", "Saved", "Config", "WindowsServer", "AstroServerSettings.ini");
        var line = System.IO.File.ReadLines(ini).FirstOrDefault(l => l.StartsWith("ServerName=", StringComparison.OrdinalIgnoreCase));
        if (line != null) name = line.Substring("ServerName=".Length).Trim();
    }
    catch { } // the file is missing or being rewritten: fall back to the service name
    var response = new GameQueryResponse
    {
        Success = true,
        Status = "online",
        Protocol = "custom_script",
        Address = address,
        Hostname = address + ":" + ThisService.GamePort,
        Name = string.IsNullOrEmpty(name) ? ThisService.Name : name,
        GameType = "ASTRONEER",
        Map = Str("saveGameName"),
        NumPlayers = Math.Max(Int("playersInGame"), players.Count),
        MaxPlayers = Int("maxInGamePlayers") > 0 ? Int("maxInGamePlayers") : ThisService.Slots,
        NumSpectators = 0,
        MaxSpectators = 0,
        Retries = 0,
        Players = players
    };
    var build = Str("build");
    if (build.Length > 0) response.Rules["Version"] = build;
    var advertised = Str("serverName");
    if (advertised.Length > 0) response.Rules["AdvertisedName"] = advertised;
    var url = Str("serverURL");
    if (url.Length > 0) response.Rules["ServerURL"] = url;
    if (root.TryGetProperty("hasServerPassword", out var hp)) response.Rules["password"] = hp.ValueKind == System.Text.Json.JsonValueKind.True ? "1" : "0";
    Globals.ReturnValue = response;
}

