bool Shell(string cmd, out string text)
{
    using (var process = Process.Start(new ProcessStartInfo("/bin/sh", new[] { "-c", cmd }) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false }))
    {
        var stderr = process.StandardError.ReadToEndAsync();
        text = process.StandardOutput.ReadToEnd() + stderr.Result;
        process.WaitForExit();
        return process.ExitCode == 0;
    }
}

//refAssemblies: System.Diagnostics.Process.dll
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

// The server rewrites Engine.ini whenever it runs and drops [URL] Port when it equals the built-in default, so a
// port change made later in the panel would never reach it. Before every start: [URL] Port = the service's game port
// and network encryption off (current game clients only join a dedicated server without encryption).
var root = Path.GetFullPath((string)ThisService.RootDirectory);
var dir = Path.Combine(root, "Astro", "Saved", "Config", "WindowsServer");
var file = Path.Combine(dir, "Engine.ini");
var wanted = new (string Section, string Key, string Value)[]
{
    ("URL", "Port", ThisService.GamePort.ToString()),
    ("SystemSettings", "net.AllowEncryption", "False"),
};

var existed = File.Exists(file);
var dirExisted = Directory.Exists(dir);
var lines = existed ? File.ReadAllLines(file).ToList() : new List<string>();
var changed = false;
foreach (var w in wanted)
{
    var header = "[" + w.Section + "]";
    var start = lines.FindIndex(l => l.Trim().Equals(header, StringComparison.OrdinalIgnoreCase));
    if (start < 0)
    {
        if (lines.Count > 0 && lines[lines.Count - 1].Trim().Length > 0) lines.Add("");
        lines.Add(header);
        lines.Add(w.Key + "=" + w.Value);
        changed = true;
        continue;
    }
    var end = lines.FindIndex(start + 1, l => l.TrimStart().StartsWith("["));
    if (end < 0) end = lines.Count;
    var keyLines = Enumerable.Range(start + 1, end - start - 1)
        .Where(i => lines[i].Split('=')[0].Trim().Equals(w.Key, StringComparison.OrdinalIgnoreCase)).ToList();
    if (keyLines.Count == 1 && lines[keyLines[0]].Trim() == w.Key + "=" + w.Value) continue;
    // Exactly one line with the value (a duplicate Port line would leave the server guessing).
    foreach (var i in keyLines.OrderByDescending(i => i)) lines.RemoveAt(i);
    lines.Insert(start + 1, w.Key + "=" + w.Value);
    changed = true;
}
if (!changed) return;

Directory.CreateDirectory(dir);
File.WriteAllText(file, string.Join(Environment.NewLine, lines) + Environment.NewLine);
ScriptConsole.WriteLine((object)("Engine.ini: game port " + ThisService.GamePort + ", network encryption off."));
if (!existed && System.OperatingSystem.IsLinux())
{
    // Scripts run as root: hand the new file to the service user like the rest of the service files.
    var args = new List<string> { "--reference=" + root, file };
    if (!dirExisted) args.Add(dir);
    using (var p = Process.Start(new ProcessStartInfo("chown", args) { UseShellExecute = false }))
        p.WaitForExit();
}
